import openpyxl

wb = openpyxl.load_workbook('/root/temp_pptx/ppt/embeddings/Microsoft_Excel_Worksheet.xlsx', data_only=False)
sheet = wb.active

for row in sheet.iter_rows():
    row_values = []
    for cell in row:
        if cell.data_type == 'f':
            row_values.append(f"FORMULA:{cell.value}")
        else:
            row_values.append(cell.value)
    print(row_values)
